        self.apply_tone(word, .rising_glottalized);
    } else if (self.buffer_effective[tone_index.?].tone != .rising_glottalized) {
        // Override other tone to rising_glottalized.
        // Reset tone.
        self.reset_tone(word, tone_index.?);
        // Apply tone.
        self.apply_tone(word, .rising_glottalized);
    } else if (self.buffer_effective[tone_index.?].tone == .rising_glottalized) {
