+        &.{ 1, 0, 9 }, // literal J at word start.
+        &.{ 1, 0, 22 }, // literal W at word start.
+        &.{ 1, 0, 25 }, // literal Z at word start.
+        &.{ 2, 0, 26, 0, 26 }, // circumflex apply.
+        &.{ 2, 0, 0, 0, 48 }, // breve / horn trigger.
