+        &.{ 4, 0, 32, 0, 34, 0, 26, 0, 31 }, // GI tone placement family.
+        &.{ 3, 0, 40, 0, 26, 0, 31 }, // OA tone placement family.
+        &.{ 5, 0, 26, 0, 44, 2, 0, 0, 26, 0, 31 }, // reset before suffix.
+        &.{ 5, 0, 26, 0, 26, 0, 26, 1, 0, 0, 26 }, // backspace around literal tail.
